mapper.select:
SELECT DISTINCT mus.FACTORY_CODE, mus.MOULD_CODE, mmi.MOULD_NO FROM t_mdm_mould_use_status mus INNER JOIN t_mdm_model_info mmi ON mmi.MOULD_CODE = mus.MOULD_CODE AND mmi.FACTORY_CODE = mus.FACTORY_CODE INNER JOIN t_mdm_product_model_relation pmr ON pmr.MOULD_CODE = mus.MOULD_CODE AND pmr.FACTORY_CODE = mus.FACTORY_CODE WHERE mus.MOULD_STATUS = 1 AND mus.FACTORY_CODE = #{factoryCode,jdbcType=VARCHAR} AND mus.YEAR = #{year,jdbcType=DECIMAL} AND mus.MONTH = #{month,jdbcType=DECIMAL} AND pmr.PRODUCT_CODE IN
#{productCode,jdbcType=VARCHAR}
AND mmi.MOULD_NO = #{mouldNo,jdbcType=VARCHAR}

SELECT DISTINCT mdmp.FACTORY_CODE, mdmp.MACHINE_CODE AS MOULD_CODE, mdmp.BEGIN_DATE, mdmp.END_DAY, mmi.MOULD_NO FROM t_mdm_device_maintenance_plan mdmp INNER JOIN t_mdm_model_info mmi ON mmi.MOULD_CODE = mdmp.MACHINE_CODE AND mmi.FACTORY_CODE = mdmp.FACTORY_CODE INNER JOIN t_mdm_product_model_relation pmr ON pmr.MOULD_CODE = mdmp.MACHINE_CODE AND pmr.FACTORY_CODE = mdmp.FACTORY_CODE WHERE IFNULL(mdmp.IS_DELETE, 0) = 0 AND mdmp.MACHINE_TYPE = 2 AND mdmp.PLAN_TYPE = 0 AND mdmp.FACTORY_CODE = #{factoryCode,jdbcType=VARCHAR} AND mdmp.BEGIN_DATE >= #{productionStartDate,jdbcType=DATE} AND mdmp.END_DAY <= #{productionEndDate,jdbcType=DATE} AND pmr.PRODUCT_CODE IN
#{productCode,jdbcType=VARCHAR}
AND mmi.MOULD_NO = #{mouldNo,jdbcType=VARCHAR}
